package com.together.couple;
import android.app.*;import android.content.*;import android.media.*;import android.os.Build;import androidx.core.app.NotificationCompat;import androidx.core.app.Person;import com.google.firebase.messaging.RemoteMessage;import io.capawesome.capacitorjs.plugins.firebase.messaging.MessagingService;
public class IncomingCallService extends MessagingService {
@Override public void onMessageReceived(RemoteMessage message){var data=message.getData();String kind=data.get("kind"),id=data.get("call_id");if(id==null||(!"call".equals(kind)&&!"call_cancel".equals(kind))){super.onMessageReceived(message);return;}NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if("call_cancel".equals(kind)){manager.cancel(id.hashCode());sendBroadcast(new Intent(getPackageName()+".CALL_ENDED").setPackage(getPackageName()).putExtra("id",id));return;}long expires;try{expires=Long.parseLong(data.getOrDefault("expires_at","0"));java.util.UUID.fromString(id);}catch(Exception error){return;}if(expires<=System.currentTimeMillis())return;
if(Build.VERSION.SDK_INT>=26){NotificationChannel channel=new NotificationChannel("incoming_calls","Incoming calls",NotificationManager.IMPORTANCE_HIGH);channel.setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_RINGTONE),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION_RINGTONE).build());channel.enableVibration(true);manager.createNotificationChannel(channel);}
String name=data.getOrDefault("caller_name","Your partner");Intent view=new Intent(this,IncomingCallActivity.class).putExtra("id",id).putExtra("name",name).putExtra("expires",expires).putExtra("kind",data.getOrDefault("call_kind","audio"));
PendingIntent full=PendingIntent.getActivity(this,id.hashCode(),view,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
PendingIntent answer=PendingIntent.getActivity(this,(id+"answer").hashCode(),new Intent(this,MainActivity.class).putExtra("call_id",id).putExtra("call_action","answer"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
PendingIntent decline=PendingIntent.getBroadcast(this,(id+"decline").hashCode(),new Intent(this,CallDeclineReceiver.class).putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
var builder=new NotificationCompat.Builder(this,"incoming_calls").setSmallIcon(R.drawable.together_launch).setContentTitle(name).setContentText("Incoming "+data.getOrDefault("call_kind","audio")+" call").setCategory(NotificationCompat.CATEGORY_CALL).setPriority(NotificationCompat.PRIORITY_MAX).setOngoing(true).setContentIntent(full).setTimeoutAfter(expires-System.currentTimeMillis()).setStyle(NotificationCompat.CallStyle.forIncomingCall(new Person.Builder().setName(name).setImportant(true).build(),decline,answer));
if(Build.VERSION.SDK_INT<34||manager.canUseFullScreenIntent())builder.setFullScreenIntent(full,true);var notification=builder.build();notification.flags|=Notification.FLAG_INSISTENT;try{manager.notify(id.hashCode(),notification);}catch(SecurityException ignored){}
}
}